from typing import Dict, List, Tuple

class Config:
    def __init__(self):
        self.weights = {
            'W1': np.random.rand(10, 5),
            'W2': np.random.rand(5, 3),
            'W3': np.random.rand(3, 1),
            'W4': np.random.rand(1, 1)
        }
        self.learning_rate = 0.01

    def update_weights(self):
        # Enforce strict loop order: W3 -> W4 -> W1 -> W2
        order = ['W3', 'W4', 'W1', 'W2']
        for w_name in order:
            self.weights[w_name] *= (1 - self.learning_rate)
        return self.weights

    def get_weights(self) -> Dict[str, np.ndarray]:
        return self.weights

